// ========================================
// NODO 1: Extraer mensaje + cargar sesión
// ========================================
// Lee el mensaje de Telegram, extrae chatId/texto,
// carga la sesión desde staticData y determina el estado actual.

const chatId =
  $json?.message?.chat?.id ??
  $json?.chat?.id ??
  $json?.message?.from?.id ??
  null;

const text = ($json?.message?.text ?? $json?.text ?? '').trim();
const firstName = $json?.message?.from?.first_name ?? '';

// Cargar sesión
const store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};
const sess = store.sessions[chatId] || {};

// Detectar /start -> reiniciar sesión
if (text === '/start') {
  store.sessions[chatId] = { state: 'NEW', chatId };
  return [
    {
      json: {
        chatId,
        text,
        firstName,
        state: 'NEW',
        session: { state: 'NEW', chatId }
      }
    }
  ];
}

// Si no hay estado, es nuevo
const state = sess.state || 'NEW';

return [
  {
    json: {
      chatId,
      text,
      firstName,
      state,
      session: sess
    }
  }
];

// ========================================
// Estado NEW: Bienvenida + pedir cédula
// ========================================
const chatId = $json.chatId;
const firstName = $json.firstName || '';

const reply = '¡Hola' + (firstName ? ' ' + firstName : '') +
  '! 😊 Soy *ARA*, tu asistente virtual de Netlife.\n\n' +
  'Para brindarte una mejor atención, por favor envíame tu *cédula* (10 dígitos) o *RUC* (13 dígitos), solo números.';

// Guardar estado
const store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};
store.sessions[chatId] = { state: 'AWAIT_ID', chatId };

return [{ json: { chatId, reply } }];

// ========================================
// Estado AWAIT_ID: Validar cédula/RUC
// ========================================
// Extrae dígitos, valida formato 10 o 13.
// Si inválido -> responde error y queda en AWAIT_ID.
// Si válido -> pasa al WS (sin reply, el siguiente nodo maneja).

const chatId = $json.chatId;
const text = $json.text;
const session = $json.session || {};

// Extraer solo dígitos
const cleaned = text.replace(/\D/g, '');

// Validar: exactamente 10 (cédula) o 13 (RUC)
if (cleaned.length !== 10 && cleaned.length !== 13) {
  return [{
    json: {
      chatId,
      reply: '❌ El número ingresado no parece ser una *cédula* (10 dígitos) ni un *RUC* (13 dígitos).\n\nPor favor, inténtalo de nuevo (solo números):',
      skipWS: true
    }
  }];
}

// Válido -> pasar al WS
return [{
  json: {
    chatId,
    identificacion: cleaned,
    skipWS: false
  }
}];

// ========================================
// Procesar respuesta WS: filtrar SOLO activos
// ========================================
// Lee la respuesta del WS, filtra puntos con estado 'Activo',
// y decide el siguiente estado:
//   0 activos -> HUMAN (escalar)
//   1 activo  -> MAIN_MENU (auto-selecciona)
//   N activos -> AWAIT_PUNTO (pedir selección)

const d = $input.first().json;
const chatId = $('Extraer Mensaje y Sesion').first().json.chatId;
const identificacion = $('Validar Identificacion').first().json.identificacion;

const store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};

// Intentar extraer datos del WS
var puntos = [];
var nombreCliente = '';
var contrato = '';

try {
  // Adaptar según estructura real de tu WS
  // Estructura esperada: d.datos.puntos[] o d.puntos[] o similar
  var datos = d.datos || d.data || d;
  puntos = datos.puntos || datos.servicios || [];
  if (!Array.isArray(puntos)) puntos = [];
  nombreCliente = datos.nombreCliente || datos.nombre || datos.razonSocial || '';
  contrato = datos.contrato || datos.numContrato || '';
} catch(e) {
  puntos = [];
}

// SOLO ACTIVOS
var activos = puntos.filter(function(p) {
  var est = String(p.estado || '').trim().toLowerCase();
  return est === 'activo';
});

// Armar sesión
var sess = {
  state: '',
  chatId: chatId,
  identificacion: identificacion,
  nombreCliente: nombreCliente,
  contrato: contrato,
  puntosActivos: activos.map(function(p) {
    return {
      puntoId: p.puntoId || p.id || null,
      login: p.login || p.loginAux || '',
      nombrePlan: p.nombrePlan || p.plan || '',
      ciudad: p.ciudad || '',
      telefonos: p.telefonos || ''
    };
  }),
  selectedPuntoId: null,
  selectedLogin: null
};

var reply = '';
var nombre = nombreCliente ? ', ' + nombreCliente : '';

if (activos.length === 0) {
  // Sin servicio activo
  sess.state = 'AWAIT_ID';

  // Limpiar identificación para que reintente
  reply = 'No encontré un servicio *Activo* asociado a la identificación *' + identificacion + '*.' +
    '\n\nPor favor verifica tu *cédula* (10 dígitos) o *RUC* (13 dígitos) y envíamela nuevamente.';

} else if (activos.length === 1) {
  // Un solo activo -> auto-seleccionar
  var p = activos[0];
  sess.state = 'MAIN_MENU';
  sess.selectedPuntoId = p.puntoId || p.id;
  sess.selectedLogin = p.login || p.loginAux;

  reply = '✅ Identificación validada' + nombre + '\n' +
    'Servicio activo: *' + (sess.selectedLogin || 'N/A') + '* | ' + (p.nombrePlan || p.plan || '') + '\n\n' +
    '¿En qué puedo ayudarte hoy? Elige una opción:\n\n' +
    '1️⃣ Saldo / fecha de pago\n' +
    '2️⃣ Reenviar factura\n' +
    '3️⃣ Formas de pago / convenios\n' +
    '4️⃣ Mi plan / servicios contratados\n' +
    '5️⃣ Soporte técnico de internet\n' +
    '6️⃣ Hablar con un asesor\n' +
    '0️⃣ Salir';

} else {
  // Múltiples activos -> elegir
  sess.state = 'AWAIT_PUNTO';

  var lineas = activos.map(function(p, i) {
    return (i + 1) + ') *' + (p.login || p.loginAux || 'sin_login') + '* | ' + (p.nombrePlan || p.plan || 'sin_plan');
  });

  reply = '✅ Identificación validada' + nombre + '\n' +
    'Tienes *' + activos.length + '* servicios activos:\n\n' +
    lineas.join('\n') + '\n\n' +
    'Responde con el *número* del servicio que deseas consultar:';
}

// Guardar sesión
store.sessions[chatId] = sess;

return [{ json: { chatId: chatId, reply: reply } }];

// ========================================
// Estado AWAIT_PUNTO: seleccionar entre activos
// ========================================
var chatId = $json.chatId;
var text = $json.text;
var session = $json.session || {};
var activos = Array.isArray(session.puntosActivos) ? session.puntosActivos : [];

var store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};

var idx = parseInt(text, 10) - 1;

if (isNaN(idx) || idx < 0 || idx >= activos.length) {
  var lineas = activos.map(function(p, i) {
    return (i + 1) + ') *' + (p.login || 'sin_login') + '* | ' + (p.nombrePlan || 'sin_plan');
  });
  var reply = 'Opción inválida 😅 Responde con un número del *1* al *' + activos.length + '*:\n\n' +
    lineas.join('\n');

  return [{ json: { chatId: chatId, reply: reply } }];
}

var chosen = activos[idx];

// Actualizar sesión
session.state = 'MAIN_MENU';
session.selectedPuntoId = chosen.puntoId;
session.selectedLogin = chosen.login;
store.sessions[chatId] = session;

var reply = '✅ Servicio seleccionado: *' + (chosen.login || '') + '* | ' + (chosen.nombrePlan || '') + '\n\n' +
  '¿En qué puedo ayudarte? Elige una opción:\n\n' +
  '1️⃣ Saldo / fecha de pago\n' +
  '2️⃣ Reenviar factura\n' +
  '3️⃣ Formas de pago / convenios\n' +
  '4️⃣ Mi plan / servicios contratados\n' +
  '5️⃣ Soporte técnico de internet\n' +
  '6️⃣ Hablar con un asesor\n' +
  '0️⃣ Salir';

return [{ json: { chatId: chatId, reply: reply } }];

// ========================================
// Estado MAIN_MENU: interpretar opción
// ========================================
// Opciones 1-6 y 0. Si texto libre -> intenta mapear o remuestra menú.

var chatId = $json.chatId;
var text = ($json.text || '').trim();
var session = $json.session || {};

var store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};

var option = parseInt(text, 10);

var MENU_TEXT = '\nElige una opción:\n\n' +
  '1️⃣ Saldo / fecha de pago\n' +
  '2️⃣ Reenviar factura\n' +
  '3️⃣ Formas de pago / convenios\n' +
  '4️⃣ Mi plan / servicios contratados\n' +
  '5️⃣ Soporte técnico de internet\n' +
  '6️⃣ Hablar con un asesor\n' +
  '0️⃣ Salir';

// === Opción 0: Salir ===
if (option === 0) {
  store.sessions[chatId] = { state: 'NEW', chatId: chatId };
  return [{ json: {
    chatId: chatId,
    reply: '¡Gracias por usar nuestro servicio! 👋\nSi necesitas algo más, envía /start para comenzar de nuevo.',
    menuOption: 0
  }}];
}

// === Opción 1: Saldo ===
if (option === 1) {
  var reply = '💳 *Información de saldo*\n\n' +
    'Servicio: *' + (session.selectedLogin || 'N/A') + '*\n\n' +
    '_(Consultando saldo y fecha máxima de pago...)_\n' +
    MENU_TEXT;
  return [{ json: { chatId: chatId, reply: reply, menuOption: 1 } }];
}

// === Opción 2: Factura ===
if (option === 2) {
  var reply = '🧾 *Reenvío de factura*\n\n' +
    'Servicio: *' + (session.selectedLogin || 'N/A') + '*\n\n' +
    '_(Procesando reenvío de factura...)_\n' +
    MENU_TEXT;
  return [{ json: { chatId: chatId, reply: reply, menuOption: 2 } }];
}

// === Opción 3: Formas de pago ===
if (option === 3) {
  var reply = '🤝 *Formas de pago y convenios*\n\n' +
    'Puedes realizar tus pagos en:\n' +
    '• Transferencia bancaria\n' +
    '• Débito automático\n' +
    '• Puntos de recaudación\n' +
    '• Pago en línea (Netlife Access)\n' +
    MENU_TEXT;
  return [{ json: { chatId: chatId, reply: reply, menuOption: 3 } }];
}

// === Opción 4: Plan ===
if (option === 4) {
  var activos = session.puntosActivos || [];
  var selected = null;
  for (var i = 0; i < activos.length; i++) {
    if (activos[i].puntoId === session.selectedPuntoId) { selected = activos[i]; break; }
  }
  var reply = '📦 *Plan y servicios contratados*\n\n' +
    'Servicio: *' + (session.selectedLogin || 'N/A') + '*\n' +
    'Plan: ' + (selected ? selected.nombrePlan || 'N/A' : 'N/A') + '\n' +
    'Ciudad: ' + (selected ? selected.ciudad || 'N/A' : 'N/A') + '\n' +
    MENU_TEXT;
  return [{ json: { chatId: chatId, reply: reply, menuOption: 4 } }];
}

// === Opción 5: Soporte técnico ===
if (option === 5) {
  var reply = '🔧 *Soporte técnico*\n\n' +
    'Para soporte básico de internet:\n' +
    '1. Reinicia tu router (desconecta 30 seg y reconecta)\n' +
    '2. Verifica las luces del equipo\n' +
    '3. Si el problema persiste, elige *6* para hablar con un asesor\n' +
    MENU_TEXT;
  return [{ json: { chatId: chatId, reply: reply, menuOption: 5 } }];
}

// === Opción 6: Asesor humano ===
if (option === 6) {
  session.state = 'HUMAN';
  store.sessions[chatId] = session;
  return [{ json: {
    chatId: chatId,
    reply: '🧑‍💻 *Conexión con asesor*\n\nTe voy a conectar con un asesor humano. Por favor espera un momento...',
    menuOption: 6
  }}];
}

// === Texto libre: pasar al AI Agent ===
// Si el usuario escribe algo que no es número del menú,
// lo enviamos al AI Agent con contexto del cliente.
return [{ json: {
  chatId: chatId,
  text: text,
  menuOption: -1,
  useAI: true,
  clienteNombre: session.nombreCliente || '',
  contrato: session.contrato || '',
  loginPunto: session.selectedLogin || '',
  session: session
}}];

