// ========================================
// Estado HUMAN: esperando asesor
// ========================================
var chatId = $json.chatId;
var text = ($json.text || '').trim().toUpperCase();
var session = $json.session || {};

var store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};

if (text === '/START') {
  store.sessions[chatId] = { state: 'NEW', chatId: chatId };
  return [{ json: { chatId: chatId, reply: 'Sesión reiniciada. Envía cualquier mensaje para comenzar.', skipSend: true } }];
}

if (text === '0' || text === 'SALIR' || text === 'MENU') {
  session.state = 'MAIN_MENU';
  store.sessions[chatId] = session;
  var reply = 'Volviendo al menú principal 😊\n\n' +
    '1️⃣ Saldo / fecha de pago\n' +
    '2️⃣ Reenviar factura\n' +
    '3️⃣ Formas de pago / convenios\n' +
    '4️⃣ Mi plan / servicios contratados\n' +
    '5️⃣ Soporte técnico de internet\n' +
    '6️⃣ Hablar con un asesor\n' +
    '0️⃣ Salir';
  return [{ json: { chatId: chatId, reply: reply } }];
}

return [{ json: {
  chatId: chatId,
  reply: '🧑‍💻 Un asesor te atenderá pronto.\nSi deseas volver al menú, escribe *0* o *menu*.\nPara reiniciar, envía /start.'
}}];

// ========================================
// Fallback: estado desconocido -> NEW
// ========================================
var chatId = $json.chatId;
var store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};
store.sessions[chatId] = { state: 'NEW', chatId: chatId };

return [{ json: {
  chatId: chatId,
  reply: '😊 Parece que algo se perdió. Empecemos de nuevo.\nPor favor envíame tu *cédula* (10 dígitos) o *RUC* (13 dígitos):'
}}];
